import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as ButtonGroup from "../../ui/button-group";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

const buttonClasses =
  "inline-flex h-9 min-w-9 items-center justify-center bg-white px-3 text-sm font-medium text-gray-900 transition hover:bg-gray-50 focus-visible:outline-2 focus-visible:outline-inset focus-visible:outline-accent-600";

// VIEW

export const view = Submodel.defineView<Model, Message>((): Html => {
  const h = html<Message>();

  return ButtonGroup.view<Message>({
    ariaLabel: "Nested editor controls",
    children: [
      ButtonGroup.view<Message>({
        ariaLabel: "Text alignment",
        children: [
          ButtonGroup.itemView<Message>({
            children: [
              h.button(
                [h.Class(buttonClasses), h.AriaLabel("Align left")],
                ["L"]
              ),
            ],
          }),
          ButtonGroup.itemView<Message>({
            children: [
              h.button(
                [h.Class(buttonClasses), h.AriaLabel("Align center")],
                ["C"]
              ),
            ],
          }),
          ButtonGroup.itemView<Message>({
            children: [
              h.button(
                [h.Class(buttonClasses), h.AriaLabel("Align right")],
                ["R"]
              ),
            ],
          }),
        ],
      }),
      ButtonGroup.view<Message>({
        ariaLabel: "Text formatting",
        children: [
          ButtonGroup.itemView<Message>({
            children: [h.button([h.Class(buttonClasses)], ["B"])],
          }),
          ButtonGroup.itemView<Message>({
            children: [h.button([h.Class(buttonClasses)], ["I"])],
          }),
          ButtonGroup.itemView<Message>({
            children: [h.button([h.Class(buttonClasses)], ["U"])],
          }),
        ],
      }),
    ],
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("button-group-nested example", () => {
  test("renders the shadcn Button Group Nested example", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(
        Scene.role("group", { name: "Nested editor controls" })
      ).toExist(),
      Scene.expect(Scene.role("group", { name: "Text alignment" })).toExist(),
      Scene.expect(Scene.role("group", { name: "Text formatting" })).toExist(),
      Scene.expect(
        Scene.role("group", { name: "Nested editor controls" })
      ).not.toHaveHandler("click")
    );
  });
});
